extern "C" {
}

extern "C" int LLVMFuzzerTestOneInput_59(const uint8_t *data, size_t size) {
    if (size == 0) return 0;
    
    // Create a FILE* from input data
    FILE *in_file = fmemopen((void *)data, size, "rb");
    if (!in_file) return 0;
    
    char errbuf[PCAP_ERRBUF_SIZE] = {0};
    
    // 1. Open pcap file from memory stream
    pcap_t *pcap = pcap_fopen_offline(in_file, errbuf);
    if (!pcap) {
        fclose(in_file);
        return 0;
    }
    
    // 2. Get datalink types
    int dlt_ext = pcap_datalink_ext(pcap);
    int dlt = pcap_datalink(pcap);
    
    // 3. Get minor version
    int minor_ver = pcap_minor_version(pcap);
    (void)minor_ver; // Prevent unused warning
    
    // 4. Convert datalink values to names and back
    const char *dlt_name = pcap_datalink_val_to_name(dlt);
    if (dlt_name) {
        int dlt_val = pcap_datalink_name_to_val(dlt_name);
        (void)dlt_val; // Prevent unused warning
    }
    
    // 5. List timestamp types
    int *tstamp_types = nullptr;
    int tstamp_count = pcap_list_tstamp_types(pcap, &tstamp_types);
    
    // 6. Set non-blocking mode (with error checking)
    char nonblock_err[PCAP_ERRBUF_SIZE] = {0};
    pcap_setnonblock(pcap, 1, nonblock_err);
    
    // 7. Try to set protocol (Linux-specific, may fail on other platforms)
    // Use a value derived from input data
    int proto_value = size > 0 ? data[0] : 0;
    pcap_set_protocol_linux(pcap, proto_value);
    
    // 8. Compile BPF filter using nopcap
    // Extract a filter string from input data
    char filter_buf[256] = {0};
    size_t filter_len = size < sizeof(filter_buf) ? size : sizeof(filter_buf) - 1;
    for (size_t i = 0; i < filter_len; i++) {
        // Only use printable characters for filter string
        filter_buf[i] = (data[i] >= 32 && data[i] < 127) ? data[i] : ' ';
    }
    filter_buf[filter_len] = '\0';
    
    struct bpf_program bpf_prog;
    int snaplen = pcap_snapshot(pcap);
    int compile_result = pcap_compile_nopcap(
        snaplen > 0 ? snaplen : 65535,
        dlt,
        &bpf_prog,
        filter_buf,
        1, // optimize
        0 // netmask
    );
    
    if (compile_result == 0) {
        // 9. Dump the compiled BPF program
        bpf_dump(&bpf_prog, 1);
        
        // 10. Free the BPF program
        pcap_freecode(&bpf_prog);
    }
    
    // 11. Try to read one packet
    struct pcap_pkthdr *pkthdr = nullptr;
    const u_char *pktdata = nullptr;
    int next_result = pcap_next_ex(pcap, &pkthdr, &pktdata);
    
    // 12. Convert status to string
    const char *status_str = pcap_statustostr(next_result);
    (void)status_str; // Prevent unused warning
    
    // 13. Process timestamp types if available
    if (tstamp_count > 0 && tstamp_types) {
        for (int i = 0; i < tstamp_count && i < 3; i++) {
            const char *tstamp_name = pcap_tstamp_type_val_to_name(tstamp_types[i]);
            (void)tstamp_name; // Prevent unused warning
        }
        // 14. Free timestamp types array
        pcap_free_tstamp_types(tstamp_types);
    }
    
    // 15. Cleanup - close pcap handle
    pcap_close(pcap);
    fclose(in_file);
    
    return 0;
}